from rdkit import Chem
from rdkit.Chem import AllChem
import numpy as np
smi={'ind':'[cH-]1c(C)c(-c2ccccc2)c2ccccc21','piv':'CC(C)(C)C(=O)[O-]','amido':'[N-](C(=O)OCC(Cl)(Cl)Cl)C([CH2-])CCc1ccccc1'}
for name,s in smi.items():
 m=Chem.AddHs(Chem.MolFromSmiles(s))
 print(name, Chem.rdMolDescriptors.CalcMolFormula(m), m.GetNumAtoms())
 for a in m.GetAtoms():
  if a.GetSymbol()!='H':print(a.GetIdx(),a.GetSymbol(),[n.GetIdx() for n in a.GetNeighbors()])
 print('embed',AllChem.EmbedMolecule(m,randomSeed=3103))
 print('mmff',AllChem.MMFFHasAllMoleculeParams(m))
 if AllChem.MMFFHasAllMoleculeParams(m):AllChem.MMFFOptimizeMolecule(m)
 else:AllChem.UFFOptimizeMolecule(m)
 Chem.MolToMolFile(m,name+'.mol')
